const BarItem = ({
  value,
  label,
  color,
  iconType,
  delay,
  maxHeight,
  maxValue,
}: {
  value: number;
  label: string;
  color: string;
  iconType: string;
  delay: number;
  maxHeight: number;
  maxValue: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const grow = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  const opacity = interpolate(frame - delay, [0, 10], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const textY = interpolate(grow, [0, 1], [20, 0]);

  const background = `linear-gradient(0deg, ${color} 0%, ${color}EE 70%, ${color}aa 100%)`;

  const currentVal = value * grow;
  let displayVal = "";
  if (value >= 1000000) {
    displayVal = (currentVal / 1000000).toFixed(1) + "M";
  } else if (value <= 100 && value > 0) {
    displayVal = currentVal.toFixed(1) + "%";
  } else {
    displayVal = Math.round(currentVal).toLocaleString("en-US");
  }

  const barHeight = Math.max((value / (maxValue || 1)) * maxHeight, 12); // Give a slight minimum height for extremely small comparative values

  return (
    <div
      style={{
        height: "100%",
        width: "22%",
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-end",
        alignItems: "center",
        position: "relative",
      }}
    >
      {/* Value Text */}
      <div
        style={{
          opacity: grow,
          transform: `translateY(${textY}px)`,
          fontFamily: "Oswald",
          fontWeight: 700,
          fontSize: "32px",
          color: "#1a1a1a",
          marginBottom: "12px",
          textAlign: "center",
          lineHeight: 1,
        }}
      >
        {displayVal}
      </div>

      {/* Bar */}
      <div
        style={{
          width: "100%",
          height: `${barHeight}px`,
          background,
          transform: `scaleY(${grow})`,
          transformOrigin: "bottom center",
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-end",
          paddingBottom: "15px",
          position: "relative",
          borderRadius: "6px 6px 0 0",
          boxShadow: "inset 0px 4px 10px rgba(255,255,255,0.2), 4px 0px 15px rgba(0,0,0,0.15)",
        }}
      />

      {/* Label */}
      <div
        style={{
          marginTop: "12px",
          fontFamily: "Inter",
          fontWeight: 700,
          fontSize: "20px",
          color: "#333",
          opacity,
          textAlign: "center",
          lineHeight: 1.2,
        }}
      >
        {label}
      </div>
    </div>
  );
};

const ListItem = ({
  label,
  text,
  color,
  delay,
  labelFontSize,
  textFontSize,
}: {
  label: string;
  text: string;
  color: string;
  delay: number;
  labelFontSize: number;
  textFontSize: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const enter = spring({
    frame: frame - delay,
    fps,
    config: { damping: 15 },
  });

  const opacity = interpolate(frame - delay, [0, 15], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const translateX = interpolate(enter, [0, 1], [50, 0]);

  return (
    <div
      style={{
        marginBottom: "20px",
        opacity,
        transform: `translateX(${translateX}px)`,
        display: "flex",
        flexDirection: "column",
        gap: "6px",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
        <div style={{ width: "16px", height: "16px", backgroundColor: color, borderRadius: "4px", flexShrink: 0 }} />
        <span style={{ fontFamily: "Inter", fontWeight: 700, fontSize: `${labelFontSize}px`, color: "#1a1a1a" }}>
          {label}
        </span>
      </div>
      <p
        style={{
          fontFamily: "Inter",
          fontSize: `${textFontSize}px`,
          color: "#444",
          lineHeight: 1.4,
          margin: 0,
          maxWidth: "100%",
          paddingLeft: "26px",
        }}
      >
        {text}
      </p>
    </div>
  );
};

